Function par <- EsPar(x As Integer)
  Define par As Boolean;
  par <- x Mod 2 = 0;
EndFunction

Function elegidos <- Filtrar(v As Vector<Integer>, condicion As Function(Integer) As Boolean)
  Define elegidos As Vector<Integer> <- vector();
  For Each elemento In v Do
    If condicion(elemento) Then
      elegidos.append(elemento);
    EndIf
  EndFor
EndFunction

Algorithm Pares
  Define numeros As Vector<Integer> <- vector();
  Define numero As Integer;
  Read numero;
  While numero <> 0 Do
    numeros.append(numero);
    Read numero;
  EndWhile
  Write Filtrar(numeros, EsPar);
EndAlgorithm
